<?php
namespace App\Models;
use App\Enums\ContentStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Spatie\Activitylog\LogOptions; use Spatie\Activitylog\Traits\LogsActivity;
class Content extends Model { use SoftDeletes,LogsActivity; protected $guarded=[]; protected function casts():array{return ['status'=>ContentStatus::class,'publish_date'=>'date'];} public function getActivitylogOptions():LogOptions{return LogOptions::defaults()->logOnly(['title','status','publish_date','pic_user_id'])->logOnlyDirty();} public function account(){return $this->belongsTo(Account::class)->withTrashed();} public function pillar(){return $this->belongsTo(Pillar::class);} public function series(){return $this->belongsTo(Series::class);} public function format(){return $this->belongsTo(Format::class);} public function pic(){return $this->belongsTo(User::class,'pic_user_id')->withTrashed();} public function platforms(){return $this->belongsToMany(Platform::class)->withPivot('account_id');} public function sourceIdea(){return $this->belongsTo(Idea::class,'source_idea_id');} public function brief(){return $this->hasOne(ContentBrief::class);} public function assets(){return $this->hasMany(Asset::class);} public function revisions(){return $this->hasMany(Revision::class);} public function comments(){return $this->hasMany(ContentComment::class);} }
